229  const otCoapOption *Message::GetNextOption(void)
   230  {
   231      otError       error = OT_ERROR_NONE;
   232      uint16_t      optionDelta;
   233      uint16_t      optionLength;
   234      uint8_t       buf[kMaxOptionHeaderSize];
   235      uint8_t *     cur  = buf + 1;
   236      otCoapOption *rval = NULL;
   237
   238      VerifyOrExit(GetHelpData().mNextOptionOffset < GetLength(), error = OT_ERROR_NOT_FOUND);
   239
   240      Read(GetHelpData().mNextOptionOffset, sizeof(buf), buf);
   241
   242      optionDelta  = buf[0] >> 4;
   243      optionLength = buf[0] & 0xf;
   244      GetHelpData().mNextOptionOffset += sizeof(uint8_t);
   245
   246      if (optionDelta < kOption1ByteExtension)
   247      {
   248          // do nothing
   249      }
   250      else if (optionDelta == kOption1ByteExtension)
   251      {
   252          optionDelta = kOption1ByteExtensionOffset + cur[0];
   253          GetHelpData().mNextOptionOffset += sizeof(uint8_t);
   254          cur++;
   255      }
   256      else if (optionDelta == kOption2ByteExtension)
   257      {
   258          optionDelta = kOption2ByteExtensionOffset + static_cast<uint16_t>((cur[0] << 8) | cur[1]);
   259          GetHelpData().mNextOptionOffset += sizeof(uint16_t);
   260          cur += 2;
   261      }
   262      else
   263      {
   264          // RFC7252 (Section 3):
   265          // Reserved for payload marker.
   266          VerifyOrExit(optionLength == 0xf, error = OT_ERROR_PARSE);
   267
   268          // The presence of a marker followed by a zero-length payload MUST be processed
   269          // as a message format error.
   270          VerifyOrExit(GetHelpData().mNextOptionOffset < GetLength(), error = OT_ERROR_PARSE);
   271
   272          ExitNow(error = OT_ERROR_NOT_FOUND);
   273      }
   274
   275      if (optionLength < kOption1ByteExtension)
   276      {
   277          // do nothing
   278      }
   279      else if (optionLength == kOption1ByteExtension)
   280      {
   281          optionLength = kOption1ByteExtensionOffset + cur[0];
   282          GetHelpData().mNextOptionOffset += sizeof(uint8_t);
   283      }
   284      else if (optionLength == kOption2ByteExtension)
   285      {
   286          optionLength = kOption2ByteExtensionOffset + static_cast<uint16_t>((cur[0] << 8) | cur[1]);
   287          GetHelpData().mNextOptionOffset += sizeof(uint16_t);
   288      }
   289      else
   290      {
   291          ExitNow(error = OT_ERROR_PARSE);
   292      }
   293
   294      VerifyOrExit(optionLength <= GetLength() - GetHelpData().mNextOptionOffset, error = OT_ERROR_PARSE);
   295
   296      rval = &GetHelpData().mOption;
   297      rval->mNumber += optionDelta;
   298      rval->mLength = optionLength;
   299
   300      GetHelpData().mNextOptionOffset += optionLength;
   301
   302  exit:
   303      if (error == OT_ERROR_PARSE)
   304      {
   305          GetHelpData().mNextOptionOffset = 0;
   306      }
   307
   308      return rval;
   309  }
   310
